const historias=`${nav()}<main><section class="hero people-home-hero">${photo('imagem principal, Histórias')}<div class="hero-copy"><span class="eyebrow">Agenda 2027 aberta · Fotografia & Filme</span><h1>Histórias que merecem ficar.</h1><p>Casamentos, famílias e momentos importantes, registados com naturalidade e sem poses forçadas.</p><div class="hero-actions"><a class="btn" href="/pessoas/contacto?servico=Agenda%202027">Ver disponibilidade</a><a class="text-link" href="#trabalho">Explorar sessões ↓</a></div></div></section><a class="christmas-home-promo" href="/pessoas/natal/"><img src="/assets/natal/cenario-provisorio.webp" alt="Ilustração do ambiente de Natal CASTA"><span><small>OUTUBRO — DEZEMBRO 2026</small><strong>O Natal já tem lugar na CASTA.</strong><em>Três formas de guardar esta época em família. Conhecer as sessões →</em></span></a><section class="booking-focus"><div><span class="eyebrow">Datas 2027</span><h2>Já têm uma data?</h2><p>Confirmem primeiro se ainda estamos disponíveis. Enviamos as opções certas para o vosso dia, sem formulários intermináveis.</p></div><article><span>01</span><h3>Casamentos</h3><p>Fotografia e vídeo em Portugal ou no estrangeiro.</p><a href="/pessoas/contacto?servico=Casamento">Pedir disponibilidade →</a></article><article><span>02</span><h3>Batizados</h3><p>Da cerimónia ao dia completo, em fotografia ou vídeo.</p><a href="/pessoas/contacto?servico=Batizado">Pedir disponibilidade →</a></article></section><section class="section services-heading" id="trabalho"><span class="eyebrow">Pessoas & Momentos</span><h2>O que queres guardar?</h2></section><section class="services services-simple services-compact"><article class="service">${serviceImage('Casamento','/pessoas/casamentos','Casamentos · Agenda 2027')}</article><article class="service">${serviceImage('Maternidade','/pessoas/maternidade','Maternidade & Bebé')}</article><article class="service">${serviceImage('Famílias e retratos','/pessoas/familias-retratos','Famílias & Retratos')}</article><article class="service">${serviceImage('Batizado','/pessoas/batizados','Batizados · Agenda 2027')}</article></section><section class="section portfolio-heading"><span class="eyebrow">Uma pequena seleção</span><h2>Histórias recentes.</h2></section>${gallery()}<section class="section about-summary"><div><span class="eyebrow">Por trás da CASTA</span><h2>Somos a Nádia e o Ruben.</h2></div><div><p class="lead">Fotografia e vídeo, com base em Alenquer.</p><p>Trabalhamos juntos para que as pessoas se sintam confortáveis e deixem de pensar na câmara. Fazemos sessões na região e acompanhamos casamentos onde for preciso.</p><div class="mini-review"><span class="stars" aria-label="5 estrelas">★★★★★</span><p>“Incríveis desde o primeiro momento. Super prestáveis, simpáticos e acolhedores.”</p></div><a class="text-link" href="/pessoas/sobre">Conhecer a CASTA →</a></div></section>${cta('Qual é a história que querem guardar?','Conta-nos a tua história','/pessoas/contacto')}</main>${footer()}`;
const wedding=`${nav()}<main><section class="hero pagehero">${weddingSlideshow()}<div class="hero-copy"><span class="eyebrow">CASTA Pessoas & Momentos</span><h1>O dia, como ele aconteceu.</h1><p>Fotografia e filme de casamento com uma abordagem natural e de reportagem. Sem transformar o dia numa produção, nem as pessoas em figurantes.</p></div></section><section class="intro"><span class="eyebrow">Casamentos</span><div><p class="lead">Há anos que acompanhamos casamentos por dentro: os planos, o nervoso miudinho, as pessoas que chegam de longe e os momentos que não estavam no alinhamento.</p><a class="btn" href="/pessoas/contacto">Pedir Guia de Casamentos</a></div></section>${weddingGallery()}<section class="section two"><div><span class="eyebrow">A nossa abordagem</span><h2>Presentes, sem interromper.</h2></div><div><p class="lead">Acompanhamos o dia com atenção ao que é real. Orientamos quando faz falta; no resto do tempo, deixamos acontecer.</p><p>Consoante a coleção, a cobertura pode reunir fotografia, segundo fotógrafo, vídeo, drone, sessão de namoro, galeria privada, filme cinematográfico, conteúdo curto para redes sociais e álbuns.</p></div></section><section class="section dark two"><div><span class="eyebrow">Fotografia + vídeo</span><h2>Uma equipa. Duas formas de ver.</h2></div><div><p class="lead">Nádia fotografa. Ruben filma. Trabalhamos com a mesma linguagem e sem competir pelo mesmo momento.</p></div></section><section class="section travel two"><div><span class="eyebrow">Onde for preciso</span><h2>O casamento não tem de ser perto de casa.</h2></div><div><p class="lead">Temos base em Alenquer, mas acompanhamos casamentos em qualquer ponto de Portugal, e no estrangeiro.</p><p>As deslocações num raio aproximado de 20 km estão incluídas. Para distâncias maiores, calculamos a deslocação de forma transparente no orçamento.</p></div></section><section class="section"><span class="eyebrow">Do primeiro contacto à entrega</span><div class="steps"><article class="step"><div><h3>Antes do casamento</h3><p>Conversamos, percebemos o ritmo do dia e alinhamos o que é mesmo importante para vocês.</p></div></article><article class="step"><div><h3>Sessão de namoro</h3><p>Quando incluída, é uma boa forma de nos conhecermos, e de perceberem que não é preciso saber posar.</p></div></article><article class="step"><div><h3>No dia</h3><p>A cobertura acompanha os momentos principais e pode estender-se por cerca de 12 a 14 horas, conforme o casamento.</p></div></article><article class="step"><div><h3>Depois</h3><p>As fotografias editadas chegam numa galeria privada; filme e peças físicas seguem a coleção escolhida.</p></div></article></div></section><section class="section faq"><span class="eyebrow">Perguntas frequentes</span><h2>O essencial, antes de falarmos.</h2><details><summary>Como verificamos disponibilidade?</summary><p>Enviem-nos a data, o local e uma ideia do dia. Respondemos com disponibilidade e o guia de coleções.</p></details><details><summary>Como funciona a reserva?</summary><p>Habitualmente é feita com um valor inicial, ficando o restante pagamento para mais perto da data.</p></details><details><summary>Fazem casamentos fora de Alenquer?</summary><p>Sim. Deslocamo-nos por todo o país e também ao estrangeiro. Num raio aproximado de 20 km a deslocação está incluída; fora dessa zona, apresentamos o respetivo valor no orçamento.</p></details></section>${cta('Vamos ver se a data ainda é vossa?','Pedir Guia de Casamentos','/pessoas/contacto')}</main>${footer()}`;
const maternity=hero('Cada fase tem o seu ritmo.','Gravidez, newborn, acompanhamento e aniversários, fotografados com tempo e à medida de cada fase.','imagem principal, maternidade')+`<section class="intro"><span class="eyebrow">Maternidade</span><div><p class="lead">Da espera aos primeiros anos, criamos espaço para guardar as mudanças que acontecem depressa demais.</p><a class="btn" href="/pessoas/contacto">Receber informações e valores</a></div></section><section class="services"><article class="service">${photo('Gravidez')}<div class="service-copy"><span class="eyebrow">28–34 semanas</span><h3>Gravidez</h3><p>Em estúdio, no exterior ou numa combinação dos dois. A janela entre as 28 e as 34 semanas tende a oferecer conforto e uma barriga bem marcada.</p></div></article><article class="service">${photo('Newborn')}<div class="service-copy"><span class="eyebrow">Ao ritmo do bebé</span><h3>Newborn</h3><p>Sessões tranquilas nos primeiros dias ou semanas, com tempo para pausas. Podem incluir pais e irmãos.</p></div></article><article class="service">${photo('Acompanhamento')}<div class="service-copy"><span class="eyebrow">As mudanças</span><h3>Acompanhamento</h3><p>Várias sessões distribuídas ao longo dos primeiros meses ou anos para contar o crescimento sem saltar capítulos.</p></div></article><article class="service">${photo('Aniversário')}<div class="service-copy"><span class="eyebrow">Um, dois, três…</span><h3>Aniversários</h3><p>Primeiro aniversário, segundo, terceiro ou quarto: uma sessão simples, temática ou com bolo, adaptada à idade da criança.</p></div></article></section>${gallery(['Gravidez','Newborn','Acompanhamento','Aniversário','Pequenos gestos'])}${cta('Em que fase estão agora?','Marcar sessão','/pessoas/contacto')}</main>${footer()}`;
const families=`${nav()}<main><section class="hero pagehero">${realSlideshow('families',familyImages,'Seleção de fotografias de família')}<div class="hero-copy"><span class="eyebrow">CASTA Pessoas & Momentos</span><h1>Pessoas como são.</h1><p>Sessões de família, casal ou individuais, com direção suficiente para se sentirem confortáveis e espaço para serem vocês.</p></div></section><section class="intro"><span class="eyebrow">Famílias & Retratos</span><div><p class="lead">Não é preciso saber posar. Pode ser uma família inteira, duas pessoas ou apenas uma, o importante é que as fotografias façam sentido para quem está nelas.</p><a class="btn" href="/pessoas/contacto">Marcar sessão</a></div></section><section class="services"><article class="service">${photo('Família')}<div class="service-copy"><span class="eyebrow">Juntos</span><h3>Família</h3><p>Sessões descontraídas para guardar a dinâmica, os gestos e as relações da vossa família.</p></div></article><article class="service">${photo('Casal')}<div class="service-copy"><span class="eyebrow">A dois</span><h3>Casal</h3><p>Uma sessão sem poses forçadas, para celebrar uma fase ou simplesmente terem fotografias onde estão os dois.</p></div></article><article class="service">${photo('Retrato individual')}<div class="service-copy"><span class="eyebrow">Só tu</span><h3>Retrato individual</h3><p>Para marcar uma mudança, ganhar confiança ou ter imagens que se parecem realmente contigo.</p></div></article></section>${realGallery('families',familyImages,'family-gallery')}${cta('Quem querem trazer para a sessão?','Marcar sessão','/pessoas/contacto')}</main>${footer()}`;
const pregnancy=detailPage('A espera também merece ficar.','Uma sessão de gravidez centrada em ti, no teu corpo e na forma como queres recordar esta fase.','Maternidade · Gravidez','Recomendamos fotografar entre as 28 e as 34 semanas, quando a barriga está bem definida e ainda existe conforto para aproveitar a sessão.',[['Quando marcar','Idealmente entre as 28 e as 34 semanas de gestação.'],['Onde','Em estúdio, no exterior ou numa combinação dos dois.'],['O que inclui','As opções começam em 110 €, com 1 hora, 40 fotografias editadas, até duas trocas de roupa e galeria online.'],['Opções completas','Podem acrescentar maquilhagem, mini-vídeo ou combinar estúdio e exterior. Os pacotes são adaptáveis.']],['Barriga','Retrato','Casal','Detalhes','À espera'],'Gravidez');
const newborn=detailPage('Os primeiros dias, sem pressa.','Uma sessão tranquila e segura, construída à volta das necessidades do bebé.','Maternidade · Newborn','O bebé dita o ritmo. Há tempo para alimentar, acalmar, mudar e parar sempre que for preciso.',[['Quando marcar','A sessão é indicada até aos 12 dias de vida, embora possamos conversar sobre outras idades.'],['Onde','No estúdio ou em vossa casa.'],['Duração','Entre 1h30 e 3h, respeitando o ritmo do bebé.'],['O que inclui','Fotografias do bebé sozinho e com pais ou irmãos, acessórios delicados, 30 fotografias editadas e galeria online, desde 160 €.']],['Bebé','Pais','Irmãos','Detalhes','Colo'],'Newborn');
const followUp=detailPage('Crescem enquanto piscamos os olhos.','Acompanhamento fotográfico para contar as mudanças do primeiro ano, ou continuar depois dele.','Maternidade · Acompanhamento','Escolhemos os momentos que fazem sentido para a vossa família e construímos uma memória coerente ao longo do tempo.',[['Crescimento','Newborn e sessões aos 3, 6 e 9 meses, terminando no primeiro aniversário.'],['Completo','Sessão mensal até aos 11 meses, primeiro aniversário, álbum e vídeo com os melhores momentos.'],['Continuidade','O acompanhamento também pode ser desenhado para o segundo ano ou outras fases importantes.'],['Entrega','Cada sessão é entregue em galeria online; os formatos finais dependem da opção escolhida.']],['Newborn','3 meses','6 meses','9 meses','Aniversário'],'Acompanhamento');
const birthdays=detailPage('Cada idade tem a sua graça.','Aniversários de 1, 2, 3 ou 4 anos, sem limitar a celebração ao primeiro.','Maternidade · Aniversários','Criamos uma sessão adequada à idade e personalidade da criança, em vez de repetir a mesma fórmula todos os anos.',[['Formato','Sessão em estúdio com cerca de 45 minutos a 1 hora.'],['Cenário','Minimalista ou temático, conforme a ideia escolhida.'],['Bolo ou tintas','Pode incluir Smash the Cake ou tintas comestíveis, quando fizer sentido.'],['Entrega','30 fotografias editadas e galeria online, desde 150 €. Existe opção com mini-vídeo.']],['Retrato','Brincadeira','Bolo','Família','Detalhes'],'Aniversário');
const familySession=visualDetailPage('A vossa família, como ela é.','Fotografias naturais para guardar relações, gestos e a confusão boa de estarem juntos.','Famílias & Retratos · Família','A sessão adapta-se à idade das crianças e à dinâmica da família. Não esperamos que ninguém fique quieto nem que saiba posar.',[['Quem participa','Pais, filhos, avós ou a combinação de pessoas que fizer sentido para vocês.'],['Onde','Em estúdio, no exterior ou num lugar importante para a família.'],['Como funciona','Damos direção quando é necessária e deixamos espaço para as relações acontecerem.'],['Antes da sessão','Ajudamos a escolher roupa, local e horário para que tudo seja simples.']],'Família',realSlideshow('families',familyImages,'Fotografias de sessões de família'),realGallery('families',familyImages,'family-gallery'));
const coupleSession=visualDetailPage('Só os dois, sem saber posar.','Uma sessão de casal leve, para celebrar uma fase ou simplesmente existirem os dois nas fotografias.','Famílias & Retratos · Casal','Não precisam de ensaiar nada. Criamos movimento, conversa e pequenas ações para as fotografias parecerem vossas.',[['Para quê','Namoro, aniversário, pedido, celebração ou apenas porque sim.'],['Onde','No exterior, em estúdio ou num lugar que faça parte da vossa história.'],['Durante a sessão','Orientamos sem transformar o momento numa sequência de poses rígidas.'],['Antes da sessão','Alinhamos roupa, ambiente e aquilo que querem sentir quando voltarem a estas imagens.']],'Casal',realSlideshow('couples',coupleImages,'Fotografias de sessões de casal'),realGallery('couples',coupleImages,'couple-gallery'));
const individualPortrait=visualDetailPage('Um retrato que se parece contigo.','Uma sessão individual com direção, tempo e espaço para encontrares a tua forma de estar diante da câmara.','Famílias & Retratos · Retrato individual','Pode marcar uma mudança, servir um projeto pessoal ou simplesmente dar-te fotografias em que te reconheces.',[['Para quem','Para qualquer pessoa, não é preciso ter experiência nem sentir-se confortável à partida.'],['Onde','Em estúdio ou no exterior, consoante a linguagem procurada.'],['Direção','Ajudamos com postura, movimento e expressão sem apagar a tua personalidade.'],['Preparação','Conversamos sobre roupa, referências e utilização das imagens antes da sessão.']],'Retrato individual',realSlideshow('portraits',portraitImages,'Seleção de retratos individuais'),realGallery('portraits',portraitImages,'portrait-gallery'));
const baptism=`${nav()}<main><section class="hero pagehero">${baptismSlideshow()}<div class="hero-copy"><span class="eyebrow">CASTA Pessoas & Momentos · Batizados</span><h1>Um dia de família.</h1><p>Fotografia ou fotografia + vídeo, da preparação à celebração, com a cobertura certa para o vosso dia.</p></div></section><section class="intro"><span class="eyebrow">Batizados</span><div><p class="lead">Há dias em que a cerimónia é só uma parte da história. Registamos a família que se reúne, os pequenos gestos e a celebração sem a tornar numa sessão permanente.</p><a class="btn" href="/pessoas/contacto">Receber Guia de Batizado</a></div></section>${baptismGallery()}<section class="section two"><div><span class="eyebrow">Cobertura à medida</span><h2>O que faz sentido para o vosso dia.</h2></div><div class="steps"><article class="step"><div><h3>Cerimónia</h3><p>O essencial do batizado, com os momentos da igreja e fotografias de família.</p></div></article><article class="step"><div><h3>Preparação + cerimónia</h3><p>O início do dia, os detalhes escolhidos e a cerimónia.</p></div></article><article class="step"><div><h3>Cerimónia + receção</h3><p>Família, convidados, ambiente, detalhes e o momento do bolo, previamente combinado.</p></div></article><article class="step"><div><h3>Cobertura completa</h3><p>Preparação, cerimónia e receção, em fotografia ou fotografia + vídeo.</p></div></article></div></section>${cta('Querem receber as opções de cobertura?','Receber Guia de Batizado','/pessoas/contacto')}</main>${footer()}`;
const about=hero('Duas pessoas, uma forma de trabalhar.','A CASTA é a Nádia na fotografia e o Ruben no vídeo. Juntos, trabalhamos com pessoas e com marcas.','Nádia e Ruben')+`<section class="section two"><div><span class="eyebrow">Nádia</span><h2>Fotografia</h2><p class="lead">Repara no gesto, na luz e naquele segundo antes de alguém perceber que está a ser fotografado.</p></div>${photo('Nádia a fotografar','portrait')}</section><section class="section dark two">${photo('Ruben a filmar','portrait')}<div><span class="eyebrow">Ruben</span><h2>Vídeo</h2><p class="lead">Pensa em movimento, som e ritmo. Tem uma relação séria com a edição, e opiniões fortes sobre música.</p></div></section><section class="intro"><span class="eyebrow">CASTA Studio</span><div><p class="lead">Trabalhamos lado a lado, entre histórias pessoais e projetos para empresas. O contexto muda. O cuidado com a imagem, não.</p></div></section>${gallery(['Backstage','Em trabalho','Os dois','Estúdio','Em reportagem'])}${cta('Têm um projeto para nos contar?','Falar connosco','/pessoas/contacto')}</main>${footer()}`;
