form?.addEventListener('submit',e=>{
  e.preventDefault();
  if(!form.reportValidity())return;
  const data=new FormData(form); const greeting=form.dataset.universe==='Comercial'?'Olá Ruben,':`Olá, CASTA ${form.dataset.universe}!`; const lines=[greeting,`Chamo-me ${data.get('Nome')}.`,`Gostaria de pedir informações sobre: ${data.get('Tipo')}.`];
  if(data.get('Data'))lines.push(`Data pretendida: ${data.get('Data')}.`);
  if(data.get('Localização'))lines.push(`Localização: ${data.get('Localização')}.`);
  if(data.get('Email'))lines.push(`Email: ${data.get('Email')}.`);
  lines.push('',String(data.get('Mensagem')||''));
  window.open(`https://wa.me/${form.dataset.whatsapp}?text=${encodeURIComponent(lines.join('\n'))}`,'_blank','noopener,noreferrer');
});

