const siteNav=document.querySelector('.nav');
if(siteNav){
  let lastScroll=window.scrollY;
  let topHover=false;
  const reveal=()=>siteNav.classList.remove('nav-hidden');
  const conceal=()=>{if(window.scrollY>90&&!topHover)siteNav.classList.add('nav-hidden')};
  window.addEventListener('scroll',()=>{const current=window.scrollY;if(current<90||current<lastScroll)reveal();else if(current>lastScroll)conceal();lastScroll=current},{passive:true});
  document.querySelector('.nav-reveal-zone')?.addEventListener('mouseenter',()=>{topHover=true;reveal()});
  siteNav.addEventListener('mouseenter',()=>{topHover=true;reveal()});
  siteNav.addEventListener('mouseleave',()=>{topHover=false;conceal()});
}

// Keep mixed portrait and landscape portfolios tightly packed without cropping.
const layoutMasonryGallery=gallery=>{
  const styles=getComputedStyle(gallery);
  const rowHeight=parseFloat(styles.gridAutoRows)||8;
  const gap=parseFloat(styles.rowGap)||10;
  gallery.querySelectorAll('.wedding-shot').forEach(figure=>{
    const img=figure.querySelector('img');
    if(!img)return;
    const place=()=>requestAnimationFrame(()=>{
      const height=img.getBoundingClientRect().height;
      if(height)figure.style.gridRowEnd=`span ${Math.ceil((height+gap)/(rowHeight+gap))}`;
    });
    if(img.complete)place();
    else img.addEventListener('load',place,{once:true});
  });
};
const masonryGalleries=[...document.querySelectorAll('.wedding-gallery')];
masonryGalleries.forEach(layoutMasonryGallery);
let masonryResizeTimer;
window.addEventListener('resize',()=>{
  clearTimeout(masonryResizeTimer);
  masonryResizeTimer=setTimeout(()=>masonryGalleries.forEach(layoutMasonryGallery),120);
},{passive:true});


// CASTA Analytics: commercial-intent event tracking
(()=>{
  const track=(name,params={})=>{
    if(typeof window.gtag!=='function')return;
    window.gtag('event',name,{
      area:location.pathname.startsWith('/marcas')?'marcas_empresas':location.pathname.startsWith('/pessoas')?'pessoas_momentos':'entrada',
      page_path:location.pathname,
      ...params
    });
  };
  const serviceFromPage=()=>{
    const p=location.pathname;
    if(p.includes('/casamentos'))return 'casamentos';
    if(p.includes('/maternidade/gravidez'))return 'gravidez';
    if(p.includes('/maternidade/newborn'))return 'newborn';
    if(p.includes('/maternidade/acompanhamento'))return 'acompanhamento';
    if(p.includes('/maternidade/aniversarios'))return 'aniversarios';
    if(p.includes('/maternidade'))return 'maternidade';
    if(p.includes('/familias-retratos/familia'))return 'familia';
    if(p.includes('/familias-retratos/casal'))return 'casal';
    if(p.includes('/retrato-individual'))return 'retrato_individual';
    if(p.includes('/familias'))return 'familias_retratos';
    if(p.includes('/batizados'))return 'batizados';
    if(p.includes('/escolar'))return 'fotografia_escolar';
    if(p.startsWith('/marcas'))return 'comercial';
    return 'geral';
  };
  document.addEventListener('click',e=>{
    const a=e.target.closest('a');
    if(!a)return;
    const href=a.href||'';
    const label=(a.textContent||a.getAttribute('aria-label')||'').trim().slice(0,100);
    const params={service:serviceFromPage(),link_text:label};
    if((href.includes('wa.me/')||href.includes('api.whatsapp.com/')||href.includes('whatsapp://'))&&!a.dataset.leadForm)track('click_whatsapp',params);
    else if(href.startsWith('mailto:'))track('click_email',params);
    else if(href.includes('instagram.com/'))track('click_social',{...params,social_network:'instagram'});
    else if(a.classList.contains('btn')&&(href.includes('/contacto')||href.includes('/booking')))track('contact_cta',params);
    else if(href.includes('clientes.castastudio.pt'))track('client_gallery_click',params);
  });
  document.querySelectorAll('.gallery,.wedding-gallery').forEach(gallery=>{
    let sent=false;
    const observer=new IntersectionObserver(entries=>{
      if(!sent&&entries.some(x=>x.isIntersecting)){
        sent=true; track('view_portfolio',{service:serviceFromPage()}); observer.disconnect();
      }
    },{threshold:.35});
    observer.observe(gallery);
  });
  const leadForm=document.getElementById('contact-form');
  if(leadForm){
    leadForm.querySelectorAll('a[href*="wa.me"],a[href*="api.whatsapp.com"],a[href^="whatsapp:"]').forEach(a=>a.dataset.leadForm='1');
    leadForm.addEventListener('submit',()=>{
      track('generate_lead',{service:leadForm.querySelector('[name="Tipo"]')?.value||serviceFromPage(),form_universe:leadForm.dataset.universe||'',contact_method:'whatsapp'});
    });
  }
})();
